import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';

// 1. Load the JSON data generated by our Java Seeder
const data = new SharedArray('k6-data', function () {
  return [JSON.parse(open('./k6-data.json'))];
});

// 2. Define the Load Profile (500 Concurrent Users over 3 minutes)
export const options = {
  scenarios: {
    constant_request_rate: {
      executor: 'constant-arrival-rate',
      rate: 5000, // Attempt exactly 5,000 requests per second
      timeUnit: '1s',
      duration: '10m',
      preAllocatedVUs: 50, // Start with 50 threads
      maxVUs: 200,         // Cap at 200 to prevent CPU meltdown on localhost
    },
  },
};

export default function () {
  const users = data[0].jwts;
  const auctions = data[0].auctionIds;

  // Pick random user and random auction for this request
  const randomUserJwt = users[Math.floor(Math.random() * users.length)];
  const randomAuction = auctions[Math.floor(Math.random() * auctions.length)];

  // Nginx Load Balancer URL
  const url = `http://localhost:80/api/bids`;
  
  // Guarantee an escalating bid amount so the Lua script accepts it.
  // __ITER is the loop number for this VU. __VU is the virtual user ID.
  // Bid starts at $500 and increases by $500 each iteration to beat the escalating getMinIncrement threshold!
  const bidAmount = ((__ITER + 1) * 50000) + __VU;

  const payload = JSON.stringify({
    auctionId: randomAuction,
    amount: bidAmount
  });

  const params = {
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${randomUserJwt}`,
    },
  };

  // The Attack
  const res = http.post(url, payload, params);

  // Validation
  check(res, {
    'is status 202 (Accepted)': (r) => r.status === 202,
    'is status 400 (Valid Lua Rejection)': (r) => r.status === 400, 
    'is status 502 (Nginx Choking)': (r) => r.status === 502,
  });

  // No sleep needed! The constant-arrival-rate executor handles the pacing natively.
}
